def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])

    # The markers lie at intersections of the long, uniform divider lines.
    row_lines = []
    for r, row in enumerate(grid):
        if Counter(row).most_common(1)[0][1] >= w * 0.8:
            row_lines.append(r)

    col_lines = []
    for c in range(w):
        if Counter(grid[r][c] for r in range(h)).most_common(1)[0][1] >= h * 0.8:
            col_lines.append(c)

    # In the simple one-cell case, the four line crossings give the
    # repeated marker color.
    corners = [grid[row_lines[i]][col_lines[j]]
               for i in (0, len(row_lines)-1)
               for j in (0, len(col_lines)-1)] if row_lines and col_lines else []
    nonline = [v for v in corners if v not in (
        Counter(grid[row_lines[0]]).most_common(1)[0][0] if row_lines else -1,
        Counter([grid[r][col_lines[0]] for r in range(h)]).most_common(1)[0][0] if col_lines else -1
    )]
    if nonline:
        return [[Counter(nonline).most_common(1)[0][0]]]

    return [[0]]
